// Process the new model creation event
const modelInfo = $input.first().json;

// Log the new model details
console.log('New Speckle Model Created:', {
  projectId: modelInfo.projectId,
  modelId: modelInfo.modelId,
  modelName: modelInfo.modelName,
  createdBy: modelInfo.createdBy,
  serverUrl: modelInfo.serverUrl,
  timestamp: modelInfo.timestamp
});

// Prepare output with formatted message
return {
  json: {
    ...modelInfo,
    message: `New model "${modelInfo.modelName}" created in project ${modelInfo.projectId}`,
    webUrl: `${modelInfo.serverUrl}/projects/${modelInfo.projectId}/models/${modelInfo.modelId}`
  }
};
